const DEFAULT={"page":"home","xp":0,"streak":0,"lastStudy":null,"answered":{},"wrong":{},"mastery":{},"lessonDone":{},"lessonChecks":{},"lessonNotes":{},"reviewAttempts":{},"cards":{},"history":[],"board":{"subject":"geral","paths":[],"returnQuiz":false},"quiz":null,"planDone":{},"settings":{"sound":true}};
const KEY='canedoQuest.v7';
let state=loadState();
let boardCtx=null,boardDrawing=false,lastPoint=null,timerHandle=null;

function clone(o){return JSON.parse(JSON.stringify(o));}
function loadState(){try{const x=JSON.parse(localStorage.getItem(KEY));return x?validateProgress(x):clone(DEFAULT)}catch(e){return clone(DEFAULT)}}
function merge(base,extra){if(!extra||typeof extra!=='object'||Array.isArray(extra))return base;for(const k of Object.keys(extra)){if(['__proto__','prototype','constructor'].includes(k))continue;if(extra[k]&&typeof extra[k]==='object'&&!Array.isArray(extra[k])&&base[k]&&typeof base[k]==='object'&&!Array.isArray(base[k]))merge(base[k],extra[k]);else base[k]=extra[k]}return base}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){toast('Não foi possível salvar. Exporte seu progresso antes de fechar.');return false}}
function esc(s){return String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]));}
function toast(msg){const el=document.querySelector('#toast');if(!el)return;el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}
function todayKey(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function touchStudy(){const t=todayKey();if(state.lastStudy!==t){const y=new Date(); y.setHours(0,0,0,0); const last=state.lastStudy?new Date(state.lastStudy+'T00:00:00'):null; if(last){const diff=Math.round((y-last)/86400000);state.streak=diff===1?state.streak+1:1}else state.streak=1;state.lastStudy=t;}save()}
function navButtons(){const items={home:['⌂','Início','Seu próximo passo'],study:['📖','Trilha','Conteúdo guiado'],review:['🔁','Revisar','Fixar o que viu'],sim:['🎯','Provas','Simulados e avaliação']};return Object.entries(items).map(([id,a])=>`<button class="${state.page===id?'active':''}" onclick="go('${id}')"><span class="icon">${a[0]}</span><span><strong>${a[1]}</strong><small>${a[2]}</small></span></button>`).join('')}
function moreMenu(){return `<div class="more-panel" id="more-panel"><div class="more-head"><div><div class="eyebrow">ATALHOS</div><h3>Mais ferramentas</h3><p>Elas continuam disponíveis, mas ficam fora do caminho principal.</p></div><button class="icon-btn" onclick="toggleMore()" aria-label="Fechar">×</button></div><div class="more-grid"><button onclick="go('train');toggleMore()"><b>⚡</b><span><strong>Treinar</strong><small>Questões sob medida</small></span></button><button onclick="go('errors');toggleMore()"><b>🧩</b><span><strong>Meus erros</strong><small>Questões para corrigir</small></span></button><button onclick="go('plan');toggleMore()"><b>🗓</b><span><strong>Plano</strong><small>19 dias de estudo</small></span></button><button onclick="go('cards');toggleMore()"><b>🧠</b><span><strong>Flashcards</strong><small>Revisão rápida</small></span></button><button onclick="go('board');toggleMore()"><b>✏️</b><span><strong>Lousa</strong><small>Rascunhar e resolver</small></span></button><button onclick="go('sources');toggleMore()"><b>📚</b><span><strong>Fontes</strong><small>Referências e dados</small></span></button></div></div>`;}
function toggleMore(){document.querySelector('#more-panel')?.classList.toggle('open')}
function shell(title=''){document.body.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">CQ</div><div><div class="brand-title">Canedo Quest</div><div class="brand-sub">ESCOLA DE CONCURSO</div></div></div><nav class="nav">${navButtons()}</nav><button class="more-nav" onclick="toggleMore()"><span class="icon">☰</span><span><strong>Mais</strong><small>Ferramentas</small></span></button><div class="sidebar-footer"><div class="small">Prova objetiva</div><strong>18/10/2026 · 15h</strong><div class="small">40 questões · 3h</div></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" onclick="toggleMore()" aria-label="Abrir ferramentas">☰</button><strong>${esc(title||'Painel')}</strong><div class="topbar-right"><span class="pill pill-streak">🔥 ${currentStreak()} ${currentStreak()===1?'dia':'dias'}</span><span class="pill pill-xp">⭐ ${state.xp} XP</span><span class="pill pill-day">D-${daysLeft()}</span></div></header><div class="content" id="content"></div></main></div>${moreMenu()}<div class="sound-toggle"><button class="icon-btn" onclick="toggleSound()" aria-label="Alternar som">${state.settings?.sound===false?'🔇':'🔊'}</button></div><div id="toast" class="toast" role="status" aria-live="polite"></div>`;}
function currentStreak(){if(!state.lastStudy)return 0;const midnight=new Date(todayKey()+'T00:00:00');const last=new Date(state.lastStudy+'T00:00:00');return Math.round((midnight-last)/86400000)<=1?state.streak:0}
function daysLeft(){const target=new Date('2026-10-18T15:00:00-03:00');return Math.max(0,Math.ceil((target-Date.now())/86400000));}
function pct(n,d){return d?Math.round(n/d*100):0}
function masteryFor(s){return state.mastery[s]||{right:0,total:0,byTopic:{}}}
function masteryPct(s){const m=masteryFor(s);return pct(m.right,m.total)}
function qPool(s=null,d=null){return QUESTIONS.filter(q=>(!s||q.s===s)&&(!d||q.d===d));}
function shuffle(a){const out=[...a];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
function chooseQuestions(s,n,d=null){const pool=qPool(s,d);return shuffle(pool).slice(0,Math.min(n,pool.length));}
function subjectName(s){return SUBJECTS[s]?.[1]||s}
function addXP(n){state.xp+=n;}
function recordAnswer(q,correct){const prev=state.answered[q.uid]||{};const attempts=(prev.attempts||0)+1;const firstCorrect=prev.attempts?prev.firstCorrect:correct;state.answered[q.uid]={correct,d:q.d,t:q.t,s:q.s,ts:Date.now(),attempts,firstCorrect,lastCorrect:correct};if(correct)delete state.wrong[q.uid];else state.wrong[q.uid]=true;const m=state.mastery[q.s]||{right:0,total:0,byTopic:{}};m.total++;if(correct)m.right++;m.byTopic[q.t]=m.byTopic[q.t]||{r:0,t:0};m.byTopic[q.t].t++;if(correct)m.byTopic[q.t].r++;state.mastery[q.s]=m;const now=Date.now();const intervals=correct?[10*60e3,24*3600e3,3*86400e3,7*86400e3,14*86400e3]:[10*60e3,60*60e3,24*3600e3];const streak=correct?(prev.correctStreak||0)+1:0;state.answered[q.uid].correctStreak=streak;const step=correct?Math.min(streak-1,intervals.length-1):0;state.answered[q.uid].nextReview=now+intervals[step];addXP(correct?(q.d==='hard'?20:q.d==='expert'?30:10):2);touchStudy();}
function uiSound(kind='tap'){if(state.settings?.sound===false)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=window.__cqAudio||(window.__cqAudio=new C());if(ctx.state==='suspended')ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();const now=ctx.currentTime;const cfg={tap:[520,.045,.012],good:[660,.11,.018],bad:[220,.09,.014],unlock:[780,.18,.024]}[kind]||[520,.045,.012];o.type='sine';o.frequency.setValueAtTime(cfg[0],now);o.frequency.exponentialRampToValueAtTime(cfg[0]*(kind==='good'?1.18:kind==='bad'?.82:1),now+cfg[1]);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(cfg[2],now+.01);g.gain.exponentialRampToValueAtTime(.0001,now+cfg[1]);o.connect(g);g.connect(ctx.destination);o.start(now);o.stop(now+cfg[1]+.02);}catch(e){}}
function toggleSound(){state.settings=state.settings||{};state.settings.sound=state.settings.sound===false;save();uiSound('tap');render();}
function guidedNext(){const order=['design','pt','info','math','direito','municipio'];const pending=order.map(s=>({s,i:MODULES[s].findIndex((_,i)=>!state.lessonDone[`${s}:${i}`]),ratio:Object.keys(state.lessonDone).filter(k=>k.startsWith(s+':')).length/MODULES[s].length})).filter(x=>x.i>=0).sort((a,b)=>a.ratio-b.ratio);return pending.length?{type:'lesson',s:pending[0].s,i:pending[0].i}:{type:'practice'};}
function guidedAction(){const due=QUESTIONS.filter(q=>state.answered[q.uid]?.nextReview<=Date.now());if(due.length)return {type:'review',count:Math.min(5,due.length),items:due,reason:`Você tem ${due.length} revisões agendadas para agora.`};return guidedNext();}
function guidedLabel(){const a=guidedAction();if(a.type==='review')return {eyebrow:'REVISÃO RECOMENDADA',title:'Corrija seus erros antes de avançar',desc:a.reason,button:'Revisar agora'};if(a.type==='lesson'){const m=MODULES[a.s][a.i];return {eyebrow:'SEU PRÓXIMO PASSO',title:m[0],desc:`${subjectName(a.s)} · aula ${a.i+1} de ${MODULES[a.s].length} · cerca de ${LESSONS[a.s]?.[a.i]?.minutes||8} min`,button:'Continuar aula'};}return {eyebrow:'PRÓXIMO DESAFIO',title:'Treino misto final',desc:'Você terminou a trilha de conteúdo. Agora é hora de consolidar com questões.',button:'Começar treino'};}
function startGuided(){const a=guidedAction();if(a.type==='review'){startQuiz(shuffle(a.items).slice(0,a.count),'errors-guided');return;}if(a.type==='lesson'){lesson(a.s,a.i);return;}startAdaptive();}
function guidedContinue(s,i){startGuided();}
function go(page){if(timerHandle)clearInterval(timerHandle);state.page=page;state.quiz=null;save();render();}
function home(){shell('Seu próximo passo');const c=document.querySelector('#content');const total=QUESTIONS.length,done=Object.keys(state.answered).length;const g=guidedLabel();const lessonCount=sumModules();const lessonDone=Object.keys(state.lessonDone).length;const wrong=QUESTIONS.filter(q=>state.wrong[q.uid]);const overall=Math.round(50*(Math.min(lessonDone,lessonCount)/Math.max(lessonCount,1)+Math.min(done,total)/Math.max(total,1)));c.innerHTML=`<div class="welcome-strip"><div><span class="eyebrow">CANEDO QUEST</span><h1>Vamos estudar. Eu guio você.</h1><p>Você não precisa escolher o que fazer agora. Siga o próximo passo e o app cuida da sequência.</p></div><div class="welcome-orb">✦</div></div><section class="guided-hero card"><div class="guided-copy"><div class="step-pill"><span>1</span> PRÓXIMA ATIVIDADE</div><div class="eyebrow">${g.eyebrow}</div><h2>${esc(g.title)}</h2><p>${esc(g.desc)}</p><div class="guided-flow"><span class="flow-dot done">✓</span><span class="flow-line active"></span><span class="flow-dot current">2</span><span class="flow-line"></span><span class="flow-dot">3</span><span class="flow-line"></span><span class="flow-dot">4</span></div><div class="flow-labels"><span>Aprender</span><span>Praticar</span><span>Revisar</span><span>Testar</span></div><button class="btn primary btn-big" onclick="startGuided()">▶ ${g.button}</button></div><div class="guided-side"><div class="progress-ring" style="background:conic-gradient(from 210deg,var(--accent) 0 ${overall}%,#1b2f47 ${overall}% 100%)"><div><strong>${overall}%</strong><span>progresso</span></div></div><p><strong>${lessonDone}</strong> de ${lessonCount} aulas concluídas</p><p><strong>${done}</strong> questões respondidas</p>${wrong.length?`<span class="attention-badge">🧩 ${wrong.length} para revisar</span>`:`<span class="calm-badge">✓ Sem erros pendentes</span>`}</div></section><section class="quick-progress"><div><div class="eyebrow">SEM PRESSA</div><h2>Seu único objetivo agora: terminar o passo atual.</h2><p>Provas, flashcards, lousa e outras ferramentas ficam em <strong>Mais</strong> para não poluir a tela principal.</p></div><button class="btn" onclick="go('study')">Ver trilha</button></section><section class="home-secondary"><div class="mini-card"><span>🔥</span><div><strong>${currentStreak()}</strong><small>dias de sequência</small></div></div><div class="mini-card"><span>⭐</span><div><strong>${state.xp}</strong><small>XP acumulado</small></div></div><div class="mini-card"><span>🎯</span><div><strong>D-${daysLeft()}</strong><small>até a prova · 18/10</small></div></div></section><details class="more-info"><summary>Quero ver meu desempenho detalhado</summary><div class="detail-grid">${Object.entries(SUBJECTS).map(([s,v])=>`<div class="detail-subject"><span class="subject-icon">${v[0]}</span><div><strong>${v[1]}</strong><div class="small">${masteryPct(s)}% de acerto · ${qPool(s).length} questões</div><div class="progress-track"><div class="progress-fill" style="width:${masteryPct(s)}%"></div></div></div></div>`).join('')}</div></details>`;}
function weakest(s){const m=masteryFor(s);let arr=Object.entries(m.byTopic||{}).filter(([,v])=>v.t).sort((a,b)=>a[1].r/a[1].t-b[1].r/b[1].t);return arr.length?`Ponto fraco: ${arr[0][0]} · ${pct(arr[0][1].r,arr[0][1].t)}%`:'Ainda sem diagnóstico — faça questões para medir.'}
function sumModules(){return Object.values(MODULES).reduce((total,mods)=>total+((mods&&mods.length)||0),0)}
function moduleQuestions(s,i){return QUESTIONS.filter(q=>q.s===s&&q.modules?.includes(i));}
function dailyMission(){const day=((19-daysLeft())%PLAN.length+PLAN.length)%PLAN.length;return PLAN[day]||PLAN[0]}
function study(){shell('Trilha de estudo');const c=document.querySelector('#content');const a=guidedNext();const ss=state.studySubject&&MODULES[state.studySubject]?state.studySubject:'design';const active=a.type==='lesson'?a.s:ss;const next=a.type==='lesson'?a:guidedNext();c.innerHTML=`<div class="path-head card"><div><div class="eyebrow">TRILHA GUIADA</div><h1>📖 Um passo de cada vez.</h1><p>O conteúdo completo existe, mas você não precisa enxergar tudo para saber o que fazer agora.</p></div><div class="path-count"><strong>${Object.keys(state.lessonDone).length}</strong><span>/${sumModules()} aulas</span></div></div><section class="next-card card"><div class="next-icon">${SUBJECTS[active]?.[0]||'📚'}</div><div class="next-main"><div class="eyebrow">PRÓXIMO NA TRILHA</div>${next.type==='lesson'?`<h2>${esc(MODULES[next.s][next.i][0])}</h2><p>${esc(subjectName(next.s))} · ${esc(MODULES[next.s][next.i][1])}</p><div class="next-meta"><span>📖 ~${LESSONS[next.s]?.[next.i]?.minutes||8} min</span><span>🧭 Aula ${next.i+1} de ${MODULES[next.s].length}</span></div><button class="btn primary" onclick="startGuided()">▶ Começar esta aula</button>`:`<h2>Conteúdo concluído</h2><p>Agora consolide tudo com um treino adaptativo.</p><button class="btn primary" onclick="startGuided()">▶ Continuar</button>`}</div></section><div class="section-head"><div><h2>Escolher outra matéria</h2><p>Use quando quiser estudar fora da rota recomendada.</p></div></div><div class="subject-picker">${Object.entries(SUBJECTS).map(([sid,v])=>{const done=Object.keys(state.lessonDone).filter(k=>k.startsWith(sid+':')).length;const total=MODULES[sid].length;return `<button class="subject-choice ${sid===active?'selected':''}" onclick="selectSubject('${sid}')"><span>${v[0]}</span><div><strong>${v[1]}</strong><small>${done}/${total} aulas</small></div><i>${sid===active?'→':'›'}</i></button>`}).join('')}</div><section id="study-panel" class="guided-details">${subjectStudy(active,false)}</section>`;}
function selectSubject(s){state.studySubject=s;save();study();}
function subjectStudy(s,collapsed=false){const v=SUBJECTS[s],mods=MODULES[s];const doneCount=Object.keys(state.lessonDone).filter(k=>k.startsWith(s+':')).length;const firstOpen=mods.findIndex((_,i)=>!state.lessonDone[`${s}:${i}`]);const suggested=firstOpen<0?mods.length-1:firstOpen;return `<details class="subject-detail" ${collapsed?'':'open'}><summary><span>${v[0]}</span><div><strong>${v[1]}</strong><small>${doneCount}/${mods.length} aulas concluídas</small></div><i>⌄</i></summary><div class="module-list-clean">${mods.map((m,i)=>{const done=state.lessonDone[`${s}:${i}`];const unlocked=i===0||state.lessonDone[`${s}:${i-1}`];const isNext=i===suggested&&!done;return `<article class="module-step ${done?'done':''} ${isNext?'recommended':''} ${!unlocked?'locked':''}"><div class="step-icon">${done?'✓':!unlocked?'🔒':i+1}</div><div class="step-content"><div class="step-top"><strong>${esc(m[0])}</strong>${isNext?'<span class="now-badge">AGORA</span>':''}</div><p>${esc(m[1])}</p><small>📖 ~${LESSONS[s]?.[i]?.minutes||6} min · ${moduleQuestions(s,i).length} questões</small></div><button class="btn small" ${!unlocked?'disabled':''} onclick="lesson('${s}',${i})">${done?'Revisar':isNext?'Começar':'Abrir'}</button></article>`}).join('')}</div></details>`;}
function filterStudy(query){const q=(query||'').trim().toLowerCase();document.querySelectorAll('#module-cards .module-card').forEach(card=>{card.style.display=!q||card.dataset.search.includes(q)?'':'none'})}
function toggleLessonCheck(key,index){const a=state.lessonChecks[key]||[];a[index]=!a[index];state.lessonChecks[key]=a;save();}
function saveLessonNote(key,val){state.lessonNotes[key]=val;save();}
function completeLesson(s,i){const key=`${s}:${i}`;if(!state.lessonDone[key]){state.lessonDone[key]=true;state.xp+=12}touchStudy();uiSound('unlock');toast('Aula concluída · próximo passo desbloqueado ✅');lesson(s,i);}
function lesson(s,i){const m=MODULES[s][i],L=LESSONS[s]?.[i]||{};state.page='study';state.studySubject=s;save();shell(`${subjectName(s)} · Conteúdo ${i+1}/${MODULES[s].length}`);const c=document.querySelector('#content');const key=`${s}:${i}`;const checks=state.lessonChecks[key]||[];const prev=i>0?i-1:null,next=i<MODULES[s].length-1?i+1:null;const qs=shuffle(moduleQuestions(s,i)).slice(0,6);const acts=REVIEW_ACTIVITIES.filter(a=>a.s===s&&a.m===i);c.innerHTML=`<div class="lesson card"><div class="lesson-top"><div><div class="eyebrow">AULA COMPLETA · ${esc(subjectName(s))} · ${i+1}/${MODULES[s].length}</div><h1>${esc(m[0])}</h1><p class="lead">${esc(m[1])}</p></div><div class="lesson-time">📖 ~${L.minutes||8} min</div></div><div class="lesson-progress"><div style="width:${Math.round(((i+1)/MODULES[s].length)*100)}%"></div></div><div class="lesson-body">${(L.sections||[]).map(txt=>{const parts=txt.split('\n');return `<section><h3>${esc(parts[0])}</h3><p>${esc(parts.slice(1).join('\n'))}</p></section>`}).join('')}</div><div class="deep-box"><div class="eyebrow">🔎 LEITURA DE REFORÇO</div><h2>Conecte a matéria ao edital</h2><p>${esc(m[1])}. Depois volte ao conceito central da aula e escreva, com suas palavras, a diferença entre os termos mais próximos do assunto.</p><div class="toolbar"><button class="btn small" onclick="state.board.returnPage='study';state.board.returnQuiz=false;state.page='board';save();render()">✏️ Fazer mapa mental na lousa</button><button class="btn small" onclick="go('review')">🔁 Ir para revisão ativa</button></div></div><div class="tip"><strong>⚠️ Pegadinha para lembrar</strong><p>${esc(L.trap||'Compare conceitos próximos e confira exceções.')}</p></div><div class="study-note"><div class="section-head"><div><h2>📝 Minhas anotações</h2><p>Escreva com suas palavras. Salva automaticamente.</p></div></div><textarea aria-label="Minhas anotações desta aula" class="note-box" placeholder="Escreva regras, exemplos, dúvidas ou pegadinhas…" oninput="saveLessonNote('${key}',this.value)">${esc(state.lessonNotes[key]||'')}</textarea></div><div class="checklist"><strong>Checklist de domínio</strong>${(L.check||[]).map((x,j)=>`<label><input type="checkbox" ${checks[j]?'checked':''} onchange="toggleLessonCheck('${key}',${j})"> ${esc(x)}</label>`).join('')}</div><div class="recall-grid"><div class="section-head"><div><div class="eyebrow">REVISÃO ATIVA</div><h2>Antes de olhar a resposta</h2><p>Três exercícios de memória para consolidar o assunto.</p></div></div>${acts.map(a=>`<article class="recall-card card"><span class="tag">${a.kind==='explicar'?'EXPLICAR':a.kind==='aplicar'?'APLICAR':'ALERTA'}</span><h3>${esc(a.prompt)}</h3><textarea aria-label="Resposta: ${esc(a.prompt)}" id="${a.uid}" class="recall-input" placeholder="Digite sua resposta…" oninput="saveReviewAttempt('${a.uid}',this.value)">${esc(state.reviewAttempts[a.uid]?.text||'')}</textarea><button class="btn small" onclick="revealRecall('${a.uid}')">👁 Mostrar referência</button><div id="ans-${a.uid}" class="recall-answer hidden"><strong>Referência</strong><p>${esc(a.answer)}</p><div class="small">${esc(a.tip)}</div></div></article>`).join('')}</div>${qs.length?`<div class="quick-check card"><div class="section-head"><div><div class="eyebrow">FIXAÇÃO</div><h2>Questões deste tópico</h2><p>${qs.length} questões sorteadas do banco do módulo.</p></div><button class="btn primary" onclick="startQuiz([${qs.map(x=>JSON.stringify(x.uid)).join(',')}].map(id=>QUESTIONS.find(q=>q.uid===id)),'module','${s}',${i})">⚡ Fazer fixação</button></div>${qs.map(q=>`<div class="mini-q"><span class="difficulty ${q.d}">${q.difficulty_label}</span><span>${esc(q.q)}</span></div>`).join('')}</div>`:''}<div class="lesson-actions"><button class="btn" onclick="go('study')">← Voltar aos módulos</button>${prev!==null?`<button class="btn" onclick="lesson('${s}',${prev})">← Aula anterior</button>`:''}<button class="btn primary" onclick="${state.lessonDone[key]?`guidedContinue('${s}',${i})`:`completeLesson('${s}',${i})`}">${state.lessonDone[key]?'🚀 Próximo passo':'✅ Concluir e continuar'}</button>${next!==null&&!state.lessonDone[key]?`<button class="btn" onclick="lesson('${s}',${next})">Próxima aula →</button>`:''}<button class="btn" onclick="moduleExam('${s}',${i})">📝 Prova do módulo</button></div></div>`;}
function saveReviewAttempt(uid,text){state.reviewAttempts[uid]={text,ts:Date.now()};save();}
function revealRecall(uid){document.querySelector('#ans-'+uid)?.classList.toggle('hidden');}
function moduleExam(s,i){const pool=moduleQuestions(s,i);startQuiz(shuffle(pool).slice(0,15),'module-exam',s,i);}
function review(){shell('Revisão');const c=document.querySelector('#content');const wrong=QUESTIONS.filter(q=>state.wrong[q.uid]);const due=QUESTIONS.filter(q=>{const a=state.answered[q.uid];if(!a)return false;return a.nextReview?Date.now()>=a.nextReview:Date.now()-a.ts>=24*3600*1000});const weak=QUESTIONS.filter(q=>{const m=state.mastery[q.s]?.byTopic?.[q.t];return m&&m.t>=2&&m.r/m.t<.7});const unseen=QUESTIONS.filter(q=>!state.answered[q.uid]);const act=shuffle(REVIEW_ACTIVITIES).slice(0,9);c.innerHTML=`<div class="content-hero card"><div><div class="eyebrow">REVISÃO INTELIGENTE</div><h1>🔁 Volte ao que ainda não está firme</h1><p>Revisão não é reler tudo: é puxar da memória, confrontar erros e voltar aos pontos fracos.</p></div><div class="content-hero-badge"><strong>${wrong.length}</strong><span>erros pendentes</span></div></div><div class="grid grid-3"><article class="card"><div class="eyebrow">ERROS</div><h2>${wrong.length}</h2><p>Questões que você errou e ainda estão na fila.</p><button class="btn primary" ${wrong.length?'':'disabled'} onclick="startQuiz(shuffle(QUESTIONS.filter(q=>state.wrong[q.uid])).slice(0,20),'errors')">Revisar erros</button></article><article class="card"><div class="eyebrow">REVISÕES AGENDADAS</div><h2>${due.length}</h2><p>Questões que o sistema marcou para você rever agora.</p><button class="btn" ${due.length?'':'disabled'} onclick="startQuiz(shuffle(QUESTIONS.filter(q=>state.answered[q.uid]?.nextReview<=Date.now())).slice(0,20),'review')">Revisar hoje</button></article><article class="card"><div class="eyebrow">PONTOS FRACOS</div><h2>${weak.length}</h2><p>Questões ligadas a assuntos abaixo de 70% de acerto.</p><button class="btn" ${weak.length?'':'disabled'} onclick="startQuiz(shuffle(QUESTIONS.filter(q=>{const m=state.mastery[q.s]?.byTopic?.[q.t];return m&amp;&amp;m.t>=2&amp;&amp;m.r/m.t&lt;.7})).slice(0,20),'weak')">Atacar fraquezas</button></article></div><div class="section-head"><div><h2>🧠 Revisão ativa</h2><p>Responda sem consultar a aula. A referência só aparece quando você pedir.</p></div><button class="btn" onclick="go('cards')">Mais flashcards</button></div><div class="recall-grid">${act.map(a=>`<article class="recall-card card"><span class="tag">${esc(subjectName(a.s))}</span><h3>${esc(a.prompt)}</h3><textarea aria-label="Resposta: ${esc(a.prompt)}" class="recall-input" placeholder="Escreva de memória…" oninput="saveReviewAttempt('${a.uid}',this.value)">${esc(state.reviewAttempts[a.uid]?.text||'')}</textarea><button class="btn small" onclick="revealRecall('${a.uid}')">👁 Ver referência</button><div id="ans-${a.uid}" class="recall-answer hidden"><strong>Referência</strong><p>${esc(a.answer)}</p><div class="small">${esc(a.tip)}</div></div></article>`).join('')}</div><div class="section-head"><div><h2>🗺️ Cobertura</h2><p>${unseen.length} questões ainda não respondidas.</p></div><button class="btn primary" ${unseen.length?'':'disabled'} onclick="startQuiz(shuffle(QUESTIONS.filter(q=>!state.answered[q.uid])).slice(0,20),'new')">Fazer inéditas</button></div>`;}

function train(){shell('Treinar');const c=document.querySelector('#content');c.innerHTML=`<div class="hero"><section class="card" style="padding:25px"><div class="eyebrow">QUESTÕES</div><h1>Treino sob medida</h1><p>Você escolhe a matéria e a dificuldade. O sistema registra acertos, erros e domínio por tópico.</p><div class="toolbar"><button class="btn primary" onclick="startAdaptive()">⚡ Adaptativo</button><button class="btn" onclick="startQuizFor('design',15,'hard')">🎨 Design difícil</button><button class="btn" onclick="startQuizFor('pt',15,'hard')">📚 Português difícil</button></div></section><section class="card" style="padding:25px"><h2>Legenda</h2><p>🟢 Fácil · 🟡 Médio · 🔴 Difícil · ⚫ Desafio. A dificuldade descreve a exigência da questão, não o seu desempenho.</p></section></div><div class="section-head"><div><h2>Por matéria</h2></div></div><div class="grid grid-3">${Object.entries(SUBJECTS).map(([s,v])=>`<div class="card"><div class="subject-row"><div class="subject-icon">${v[0]}</div><div><strong>${v[1]}</strong><div class="small">${qPool(s).length} questões</div></div></div><div class="toolbar" style="margin-top:14px"><button class="btn small" onclick="startQuizFor('${s}',10,'easy')">Fácil</button><button class="btn small" onclick="startQuizFor('${s}',10,'medium')">Médio</button><button class="btn small" onclick="startQuizFor('${s}',10,'hard')">Difícil</button></div></div>`).join('')}</div>`;}
function startAdaptive(){const need=[];for(const sid of Object.keys(SUBJECTS)){const m=masteryFor(sid);const weakTopics=Object.entries(m.byTopic||{}).filter(([,v])=>v.t&&v.r/v.t<.7).map(x=>x[0]);for(const t of weakTopics)need.push(...qPool(sid).filter(q=>q.t===t));}const unique=new Map();need.forEach(q=>unique.set(q.uid,q));let pool=shuffle([...unique.values(),...QUESTIONS.filter(q=>!state.answered[q.uid])]);if(pool.length<15)pool=shuffle(QUESTIONS);startQuiz(pool.slice(0,Math.min(15,pool.length)),'practice');}
function startQuizFor(s,n,d){let pool=chooseQuestions(s,n,d);if(pool.length<n)pool=chooseQuestions(s,n);startQuiz(pool,'practice')}
function moduleDrill(s,i){let pool=moduleQuestions(s,i);startQuiz(shuffle(pool).slice(0,Math.min(12,pool.length)),'module',s,i);}
function startSingle(uid){const q=QUESTIONS.find(x=>x.uid===uid);startQuiz([q],'single')}
function mixQuestions(s,counts){let out=[];for(const [d,n] of Object.entries(counts))out.push(...chooseQuestions(s,n,d));return shuffle(out)}
function startExam(type){const pick=(s,n)=>{const base=qPool(s),hard=base.filter(q=>q.d==='hard'||q.d==='expert');const priority=type==='hard'?shuffle(hard):shuffle(base);return [...priority,...shuffle(base.filter(q=>!priority.includes(q)))].slice(0,n)};const general=type==='hard'?shuffle(QUESTIONS.filter(q=>!['pt','design'].includes(q.s))).sort((a,b)=>Number(['hard','expert'].includes(b.d))-Number(['hard','expert'].includes(a.d))).slice(0,10):shuffle([...pick('info',3),...pick('math',2),...pick('direito',3),...pick('municipio',2)]);startQuiz(shuffle([...pick('pt',10),...general,...pick('design',20)]),'exam');state.quiz.examType=type;save();}
function startQuiz(pool,mode='practice',s=null,i=null){pool=[...new Map(pool.filter(Boolean).map(q=>[q.uid,q])).values()];if(!pool.length){toast('Este tópico ainda não tem questões vinculadas. Revise a aula.');return}state.quiz={qs:pool.map(q=>q.uid),optionOrders:Object.fromEntries(pool.map(q=>[q.uid,shuffle(q.o.map((_,j)=>j))])),idx:0,answers:{},marked:{},mode,subject:s,module:i,started:Date.now(),seconds:mode==='exam'?10800:null,finished:false,scored:false};state.page=mode==='exam'?'sim':state.page;save();render();}
function renderQuiz(){const z=state.quiz;if(z.finished){renderQuizResult();return;}const q=QUESTIONS.find(x=>x.uid===z.qs[z.idx]);if(!q){z.finished=true;renderQuizResult();return}const isExam=z.mode==='exam';shell(isExam?'Simulação de prova':'Treino');const c=document.querySelector('#content');const selected=z.answers[q.uid];const answered=selected!==undefined;let remaining=z.seconds; if(isExam)remaining=Math.max(0,10800-Math.floor((Date.now()-z.started)/1000)); if(isExam&&remaining<=0){finalizeQuiz(true);return}const mins=Math.floor(remaining/60),secs=String(remaining%60).padStart(2,'0');c.innerHTML=`<div class="question-wrap"><div class="q-meta"><span>${subjectName(q.s)} · ${z.idx+1}/${z.qs.length}</span><span class="difficulty ${q.d}">${q.difficulty_label}</span>${isExam?`<span id="exam-timer" role="timer">⏱ ${mins}:${secs}</span>`:''}</div><div class="card" style="margin-top:10px;padding:25px"><div class="small">${z.mode==='exam'?'PROVA — sem correção até entregar':z.mode==='single'?'REVISÃO DE ERRO':'TREINO'} · ${esc(q.t)}</div><div class="q-text">${esc(q.q)}</div>${q.visual?'<div class="visual-question">'+q.visual+'</div>':''}<div class="choices">${(z.optionOrders?.[q.uid]||q.o.map((_,j)=>j)).map((j,k)=>`<button class="choice ${answered&&!isExam?(j===q.a?'correct':(j===selected?'wrong':'')):''} ${isExam&&selected===j?'selected':''}" ${answered&&!isExam?'disabled':''} aria-pressed="${selected===j}" onclick="answer(${j})"><span class="letter">${'ABCDEFGHIJKLMNOPQRSTUVWXYZ'[k]}</span>${esc(q.o[j])}</button>`).join('')}</div>${answered&&!isExam?`<div class="feedback ${selected===q.a?'good':'bad'}"><strong>${selected===q.a?'✅ Correto':'❌ Incorreto'}</strong><p>${esc(q.e)}</p>${q.extra?`<div class="small">${esc(q.extra)}</div>`:''}</div>`:''}<div class="quiz-actions"><button class="btn" onclick="boardFromQuiz()">✏️ Lousa</button><div class="toolbar"><button class="btn ${z.marked[q.uid]?'primary':''}" onclick="markQ()">🔖 ${z.marked[q.uid]?'Marcada':'Marcar'}</button>${z.idx>0?`<button class="btn" onclick="prevQ()">← Anterior</button>`:''}${answered||isExam?`<button class="btn primary" onclick="nextQ()">${z.idx===z.qs.length-1?(isExam?'Entregar':'Finalizar'):'Próxima →'}</button>`:''}</div></div></div>${isExam?examNav()+'<button class="btn" onclick="finalizeQuiz()">Entregar simulado agora</button>':''}</div>`;}
function answer(i){const z=state.quiz;if(!z||z.finished)return;const q=QUESTIONS.find(x=>x.uid===z.qs[z.idx]);if(!Number.isInteger(i)||i<0||i>=q.o.length)return;if(z.mode!=='exam'&&z.answers[q.uid]!==undefined)return;z.answers[q.uid]=i;if(z.mode!=='exam'){recordAnswer(q,i===q.a);uiSound(i===q.a?'good':'bad')}else uiSound('tap');save();renderQuiz();}
function nextQ(){const z=state.quiz;if(z.idx>=z.qs.length-1){finalizeQuiz(false);return}z.idx++;save();renderQuiz();}
function prevQ(){state.quiz.idx=Math.max(0,state.quiz.idx-1);save();renderQuiz();}
function markQ(){const z=state.quiz,q=QUESTIONS.find(x=>x.uid===z.qs[z.idx]);z.marked[q.uid]=!z.marked[q.uid];save();renderQuiz();}
function examNav(){const z=state.quiz;return `<div class="exam-nav"><strong>Folha de prova</strong><div class="exam-grid">${z.qs.map((uid,i)=>`<button class="exam-dot ${i===z.idx?'current':''} ${z.answers[uid]!==undefined?'answered':''} ${z.marked[uid]?'marked':''}" onclick="jumpQ(${i})">${i+1}</button>`).join('')}</div><div class="exam-legend">Respondida · Marcada · Atual</div></div>`}
function jumpQ(i){state.quiz.idx=i;save();renderQuiz();}
function finalizeQuiz(){const z=state.quiz;if(!z)return;if(z.scored){renderQuizResult();return}z.finished=true;z.scored=true;const rows=[];for(const uid of z.qs){const q=QUESTIONS.find(x=>x.uid===uid);if(!q)continue;const given=z.answers[uid];const correct=given===q.a;rows.push({q,given,correct});if(z.mode==='exam'||given===undefined)recordAnswer(q,correct)}z.result=rows;state.history.unshift({ts:Date.now(),mode:z.mode,total:rows.length,hit:rows.filter(r=>r.correct).length,score:pct(rows.filter(r=>r.correct).length,rows.length)});state.history=state.history.slice(0,30);save();renderQuizResult();}
function renderQuizResult(){if(timerHandle)clearInterval(timerHandle);const z=state.quiz;const rows=z.qs.map(uid=>{const q=QUESTIONS.find(x=>x.uid===uid);return q?{q,given:z.answers[uid],correct:z.answers[uid]===q.a}:null}).filter(Boolean);z.result=rows;const total=rows.length,hit=rows.filter(r=>r.correct).length,score=pct(hit,total);const b=rows.filter(r=>r.q.s!=='design'),sp=rows.filter(r=>r.q.s==='design');const bh=b.filter(r=>r.correct).length,sh=sp.filter(r=>r.correct).length;const bPct=pct(bh,b.length),spPct=pct(sh,sp.length);const hard=rows.filter(r=>r.q.d==='hard'||r.q.d==='expert');const hardScore=pct(hard.filter(r=>r.correct).length,hard.length);const blockCheck=z.mode==='exam'?'<div class="card exam-threshold"><div><strong>🎯 Controle dos blocos do edital</strong><p class="small">No simulado fiel, acompanhe separadamente o bloco básico e o específico. O mínimo exigido no edital é 50% em cada bloco.</p></div><div class="exam-threshold-grid"><div class="'+(bPct>=50?'ok':'warn')+'"><span>Base</span><strong>'+bPct+'%</strong><small>'+bh+'/'+b.length+' · mínimo 50%</small></div><div class="'+(spPct>=50?'ok':'warn')+'"><span>Específico</span><strong>'+spPct+'%</strong><small>'+sh+'/'+sp.length+' · mínimo 50%</small></div></div>'+(bPct<50||spPct<50?'<div class="small warn-text">⚠️ Um dos blocos ficou abaixo de 50%. Priorize esse bloco antes de buscar apenas nota geral.</div>':'<div class="small ok-text">✅ Os dois blocos atingiram pelo menos 50% neste simulado.</div>')+'</div>':'';shell(z.mode==='exam'?'Resultado da prova':'Resultado do treino');const c=document.querySelector('#content');c.innerHTML='<section class="card result-head"><div class="eyebrow">'+(z.mode==='exam'?'SIMULADO':'SESSÃO CONCLUÍDA')+'</div><div class="result-score">'+score+'<small>%</small></div><p>'+hit+'/'+total+' acertos · '+state.xp+' XP total</p><div class="toolbar" style="justify-content:center"><button class="btn primary" onclick="go(\'home\')">Voltar ao painel</button><button class="btn" onclick="startAdaptive()">Treinar pontos fracos</button></div></section>'+blockCheck+'<div class="grid grid-3" style="margin-top:18px"><div class="card"><strong>Conhecimentos básicos</strong><div class="result-score" style="font-size:42px">'+bPct+'%</div><div class="small">'+bh+'/'+b.length+'</div></div><div class="card"><strong>Design específico</strong><div class="result-score" style="font-size:42px">'+spPct+'%</div><div class="small">'+sh+'/'+sp.length+'</div></div><div class="card"><strong>Questões difíceis</strong><div class="result-score" style="font-size:42px">'+hardScore+'%</div><div class="small">'+hard.filter(r=>r.correct).length+'/'+hard.length+'</div></div></div><div class="section-head"><div><h2>Revisão</h2><p>As erradas continuam disponíveis no seu caderno de erros.</p></div></div><div class="card"><table class="table"><thead><tr><th>#</th><th>Matéria</th><th>Nível</th><th>Resultado</th></tr></thead><tbody>'+rows.map((r,i)=>'<tr><td>'+(i+1)+'</td><td>'+esc(subjectName(r.q.s))+'</td><td><span class="difficulty '+r.q.d+'">'+r.q.difficulty_label+'</span></td><td>'+(r.correct?'✅ Acertou':'❌ Errou')+' '+(r.correct?'':'<button class="btn small" onclick="startSingle(\''+r.q.uid+'\')">Revisar</button>')+'</td></tr>').join('')+'</tbody></table></div>';}
function sim(){shell('Provas');const c=document.querySelector('#content');const hist=state.history||[];const subjectCards=Object.entries(SUBJECTS).map(([sid,v])=>`<article class="card"><div class="subject-row"><div class="subject-icon">${v[0]}</div><div><strong>${v[1]}</strong><div class="small">${qPool(sid).length} questões · ${MODULES[sid].length} módulos</div></div></div><p>Prova de matéria com mistura de níveis, para verificar se a teoria está virando acerto.</p><button class="btn small primary" onclick="startSubjectExam('${sid}')">📝 Prova da matéria</button></article>`).join('');c.innerHTML=`<div class="content-hero card"><div><div class="eyebrow">CENTRAL DE PROVAS</div><h1>🎯 Prove que você aprendeu</h1><p>Use provas por matéria para fechar ciclos e simulados completos para testar resistência, tempo e consistência.</p></div><div class="content-hero-badge"><strong>40</strong><span>questões na prova</span></div></div><div class="grid grid-2"><article class="card"><div class="eyebrow">SIMULADO COMPLETO</div><h2>Simulado fiel ao formato da prova</h2><p>40 questões · 3 horas · 10 Português + 10 conhecimentos gerais + 20 Design. Correção somente no final.</p><button class="btn primary" onclick="startExam('final')">Iniciar</button></article><article class="card"><div class="eyebrow">SIMULADO DIFÍCIL</div><h2>Pressão máxima</h2><p>40 questões difíceis/desafio, para descobrir se o conhecimento aguenta interpretação e pegadinha.</p><button class="btn" onclick="startExam('hard')">Iniciar</button></article><article class="card"><div class="eyebrow">MARATONA DE REVISÃO</div><h2>60 questões</h2><p>Bloco longo misto, sem substituir a prova oficial simulada.</p><button class="btn" onclick="startMarathon()">Iniciar</button></article><article class="card"><div class="eyebrow">DIAGNÓSTICO</div><h2>Novas / não respondidas</h2><p>Prioriza questões que você ainda não respondeu.</p><button class="btn" onclick="startFreshExam()">Iniciar</button></article></div><div class="section-head"><div><h2>Provas por matéria</h2><p>Faça uma prova específica antes de voltar ao material de reforço.</p></div></div><div class="grid grid-3">${subjectCards}</div><div class="section-head"><div><h2>Histórico</h2><p>${hist.length} provas/sessões registradas.</p></div></div>${hist.length?`<div class="table-wrap card"><table><thead><tr><th>Data</th><th>Modo</th><th>Acertos</th><th>Nota</th></tr></thead><tbody>${hist.slice(0,15).map(h=>`<tr><td>${new Date(h.ts).toLocaleString('pt-BR')}</td><td>${esc(h.mode)}</td><td>${h.hit}/${h.total}</td><td>${h.score}%</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Ainda não há sessões no histórico.</div>'}`;}
function startSubjectExam(s){const counts={easy:5,medium:10,hard:7,expert:3};let pool=[];for(const [d,n] of Object.entries(counts))pool.push(...chooseQuestions(s,n,d));pool=shuffle(pool);startQuiz(pool.slice(0,Math.min(25,pool.length)),'subject-exam',s);}
function startMarathon(){let pool=shuffle(QUESTIONS);startQuiz(pool.slice(0,60),'marathon');}
function startFreshExam(){let pool=shuffle(QUESTIONS.filter(q=>!state.answered[q.uid]));if(!pool.length){toast('Você já respondeu todas as questões. Faça uma revisão.');return}startQuiz(pool.slice(0,40),'diagnostic');}
function errors(){shell('Meus erros');const c=document.querySelector('#content');const arr=QUESTIONS.filter(q=>state.wrong[q.uid]);if(!arr.length){c.innerHTML=`<div class="empty"><h2>🎉 Nenhum erro pendente</h2><p>Faça questões e o sistema vai construir seu caderno automaticamente.</p></div>`;return}c.innerHTML=`<div class="section-head"><div><h2>${arr.length} questões para revisar</h2><p>Revisite até conseguir explicar por que a alternativa certa é certa e as outras são erradas.</p></div><button class="btn primary" onclick="startQuiz(shuffle(QUESTIONS.filter(q=>state.wrong[q.uid])).slice(0,20),'errors')">Revisar agora</button></div><div class="grid grid-2">${arr.map(q=>`<div class="card"><div class="toolbar"><span class="difficulty ${q.d}">${q.difficulty_label}</span><span class="tag">${subjectName(q.s)}</span><span class="tag">${esc(q.t)}</span></div><h3>${esc(q.q)}</h3><button class="btn small" onclick="startSingle('${q.uid}')">Abrir</button></div>`).join('')}</div>`;}
function plan(){shell('Plano 19 dias');const c=document.querySelector('#content');c.innerHTML=`<div class="section-head"><div><h2>Reta final</h2><p>Use como estrutura de reforço; o adaptativo pode mudar a ordem quando seu desempenho revelar pontos fracos.</p></div></div><div class="grid">${PLAN.map(p=>`<article class="card plan-day"><div class="day-badge"><div class="small">DIA</div><div class="day-num">${p.day}</div></div><div><strong>${esc(p.title)}</strong><p>${esc(p.items)}</p></div><button class="btn ${state.planDone[p.day]?'primary':''}" onclick="togglePlan(${p.day})">${state.planDone[p.day]?'✓ Feito':'Marcar'}</button></article>`).join('')}</div>`;}
function togglePlan(d){state.planDone[d]=!state.planDone[d];touchStudy();render();}
let cardIndex=0,cardReveal=false;
function cards(){shell('Flashcards');const arr=FLASHCARDS.concat(EXTRA_FLASHCARDS);if(!arr.length){document.querySelector('#content').innerHTML='<div class="empty">Sem cards.</div>';return}const fc=arr[cardIndex%arr.length];const c=document.querySelector('#content');c.innerHTML=`<div class="flash card"><div class="eyebrow">FLASHCARD ${cardIndex%arr.length+1}/${arr.length}</div><h1>${esc(fc.front)}</h1>${cardReveal?`<div class="flash-back"><strong>Resposta</strong><p>${esc(fc.back)}</p><div class="small">${esc(fc.hint)}</div></div>`:`<p>Clique para revelar. Depois explique com suas palavras antes de virar.</p>`}<div class="toolbar" style="justify-content:center;margin-top:22px"><button class="btn primary" onclick="revealCard()">${cardReveal?'Próximo':'Revelar'}</button><button class="btn" onclick="shuffleCard()">Embaralhar</button></div></div>`;}
function revealCard(){if(cardReveal){cardIndex++;cardReveal=false}else cardReveal=true;save();cards();}
function shuffleCard(){const n=FLASHCARDS.length+EXTRA_FLASHCARDS.length;cardIndex=Math.floor(Math.random()*n);cardReveal=false;cards();}
function board(){shell('Lousa');const c=document.querySelector('#content');c.innerHTML=`<div class="section-head"><div><h2>✏️ Lousa de estudo</h2><p>Rascunhe contas, fluxos, mapas mentais, layouts ou análise de questão. O quadro é salvo automaticamente neste navegador.</p></div><div class="toolbar"><button class="btn small" onclick="boardClear()">Limpar</button><button class="btn small" onclick="boardDownload()">Baixar PNG</button><button class="btn primary small" onclick="closeBoard()">${state.board.returnQuiz?'Voltar à questão':'Fechar'}</button></div></div><div class="card board-card"><canvas id="study-board" width="1200" height="650"></canvas></div>`;initBoard();}
function initBoard(){const cv=document.querySelector('#study-board');if(!cv)return;boardCtx=cv.getContext('2d');boardCtx.fillStyle='#fff';boardCtx.fillRect(0,0,cv.width,cv.height);if(state.board.paths?.length){for(const p of state.board.paths){boardCtx.strokeStyle=p.c;boardCtx.lineWidth=p.w;boardCtx.lineCap='round';boardCtx.beginPath();p.pts.forEach((pt,i)=>i?boardCtx.lineTo(pt.x,pt.y):boardCtx.moveTo(pt.x,pt.y));boardCtx.stroke()}}cv.onpointerdown=e=>{boardDrawing=true;const r=cv.getBoundingClientRect();lastPoint={x:(e.clientX-r.left)*cv.width/r.width,y:(e.clientY-r.top)*cv.height/r.height};state.board.paths.push({c:'#0b1b2d',w:5,pts:[lastPoint]});};cv.onpointermove=e=>{if(!boardDrawing)return;const r=cv.getBoundingClientRect();const p={x:(e.clientX-r.left)*cv.width/r.width,y:(e.clientY-r.top)*cv.height/r.height};const cur=state.board.paths[state.board.paths.length-1];cur.pts.push(p);boardCtx.strokeStyle=cur.c;boardCtx.lineWidth=cur.w;boardCtx.lineCap='round';boardCtx.beginPath();boardCtx.moveTo(lastPoint.x,lastPoint.y);boardCtx.lineTo(p.x,p.y);boardCtx.stroke();lastPoint=p;};cv.onpointerup=()=>{boardDrawing=false;lastPoint=null;save()};cv.onpointerleave=()=>{boardDrawing=false;lastPoint=null;save()};}
function boardClear(){state.board.paths=[];save();board();}
function boardDownload(){const cv=document.querySelector('#study-board');const a=document.createElement('a');a.href=cv.toDataURL('image/png');a.download='canedo-quest-lousa.png';a.click();}
function boardFromQuiz(){state.board.returnQuiz=true;state.board.returnPage=state.page;save();state.page='board';render();}
function closeBoard(){if(state.board.returnQuiz&&state.quiz){state.board.returnQuiz=false;const p=state.board.returnPage||'sim';state.page=p;save();render()}else{state.board.returnQuiz=false;const p=state.board.returnPage||'home';state.board.returnPage='';save();go(p)}}
function sources(){shell('Fontes e controle de dados');const c=document.querySelector('#content');c.innerHTML=`<div class="grid grid-2"><div class="card"><h2>Fontes principais</h2><p>Use as versões oficiais como referência sempre que houver legislação ou dado local.</p><p><a href="https://www.consulpam.com.br/index.php?menu=concursos&acao=ver&id=814&tipo=bo" target="_blank">Consulpam — concurso</a></p><p><a href="https://www.consulpam.com.br/" target="_blank">Consulpam — portal</a></p><p><a href="https://www.ibge.gov.br/cidades-e-estados/go/senador-canedo.html" target="_blank">IBGE — Senador Canedo</a></p><p><a href="https://senadorcanedo.go.leg.br/" target="_blank">Câmara Municipal de Senador Canedo</a></p><p><a href="https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm" target="_blank">Constituição Federal</a></p><p><a href="https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm" target="_blank">Lei 14.133/2021</a></p><p><a href="https://www.w3.org/TR/WCAG22/" target="_blank">W3C — WCAG 2.2</a></p></div><div class="card"><h2>Seu progresso</h2><p>Salvamento automático: <strong>ativado</strong></p><p>Chave local: <code>${KEY}</code></p><div class="toolbar"><button class="btn" onclick="exportData()">⬇️ Exportar progresso</button><label class="btn" for="imp">⬆️ Importar progresso</label><input id="imp" type="file" accept="application/json" style="display:none" onchange="importData(event)"></div><p class="small">O arquivo exportado contém seus dados de estudo no navegador. Guarde uma cópia para não perder o progresso ao trocar de navegador/computador.</p></div></div>`;}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='canedo-quest-progresso.json';a.click();URL.revokeObjectURL(a.href);}
function importData(ev){const f=ev.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);const next=validateProgress(x);state=next;save();toast('Progresso importado');render()}catch(e){toast('Arquivo inválido')}};r.readAsText(f);}
function render(){if(state.page==='board')board();else if(state.quiz)renderQuiz();else if(state.page==='home')home();else if(state.page==='study')study();else if(state.page==='review')review();else if(state.page==='train')train();else if(state.page==='sim')sim();else if(state.page==='errors')errors();else if(state.page==='plan')plan();else if(state.page==='cards')cards();else if(state.page==='sources')sources();else home();}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.id==='install-app-btn')return;if(t.classList.contains('btn')||t.classList.contains('choice')||t.classList.contains('subject-choice')||t.classList.contains('more-nav')||t.closest('.more-panel'))uiSound(t.classList.contains('choice')?(t.classList.contains('correct')?'good':t.classList.contains('wrong')?'bad':'tap'):'tap')});
// Initial render is deferred until the entire question bank is loaded.
setInterval(()=>{if(document.readyState==='loading')return;const z=state.quiz;if(z?.mode==='exam'&&!z.finished){const remaining=Math.max(0,10800-Math.floor((Date.now()-z.started)/1000));if(!remaining){finalizeQuiz();return}const timer=document.querySelector('#exam-timer');if(timer)timer.textContent='⏱ '+Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0')}},1000);
